sys_variable_value.value:
(function execute(inputs, outputs) {
    var onb_req = new GlideRecord('x_snc_cpa_onboar_0_onboard_req');
    onb_req.addEncodedQuery('number='+inputs.onb_req_num);
    onb_req.query();
    var response = '';
    if(onb_req.next()) {
        var onbData = {
            onb_id: onb_req.getUniqueValue(),
            onb_number: onb_req.getValue('number'),
            onb_hire_id: onb_req.getDisplayValue('employee'),
            onb_hire_name: onb_req.getDisplayValue('employee'),
            onb_assigned_to: onb_req.getDisplayValue('assigned_to'),
            onb_opened_by: onb_req.getDisplayValue('opened_by')
        }
        response = JSON.stringify(onbData);
    }
    else {
        response = "Onboarding data not found! Unable to fetch onboarding details."
    }
    outputs.onb_data = response;
})(inputs, outputs);

